from dataclasses import dataclass


@dataclass
class Item:
    type: str
    value: float

    @property
    def adjusted_value(self) -> float:
        multipliers = {"A": 1.1, "B": 0.9, "C": 1.05}
        return self.value * multipliers.get(self.type, 1.0)


def calculate(data: list[Item]) -> float:
    return sum(item.adjusted_value for item in data)

